select i.product_id, i.store_id, i.quantity, ss.product_id as store_sale_product_id, ss.sale_date, ss.store_id as store_sale_store_id from inventory i left join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id where ss.product_id in (3, 5, 8) order by ss.sale_date desc, 6 desc;
